const PROCESSING_FEE = 5;

const SWORD_BASE_PREMIUM = 100;

const FIRST_INSURANCE_SURCHARGE = 0.1;

export const runScenario = (scenario: Scenario): ScenarioResults => {
  const results = scenario.steps.map((step) => {
    const items = step.items ?? [];
    const basePremium = items.length * SWORD_BASE_PREMIUM;
    const premium = basePremium * (1 + FIRST_INSURANCE_SURCHARGE) + PROCESSING_FEE;
    return { premium };
  });

  return { results };
};

